const email = $input.first().json;
const from = (email.from || email.fromAddress || '').toLowerCase();
const subject = (email.subject || '').toLowerCase();
const body = (email.textPlain || email.text || email.textHtml || '').replace(/<[^>]+>/g, ' ').trim();

const isReply = subject.includes('persona') || subject.includes('newsletter') || subject.includes('re:');
if (!isReply || !from || body.length < 5) {
  return [{ json: { skip: true } }];
}

return [{ json: { skip: false, fromEmail: from.match(/<([^>]+)>/)?.[1] || from, body: body.slice(0, 2000), subject } }];

const emailData = $('Parse Email').first().json;
const rows = $input.all().map(i => i.json);
const user = rows.find(r => (r.email || '').toLowerCase() === emailData.fromEmail.toLowerCase());
if (!user) {
  return [{ json: { success: false, error: 'Utilisateur inconnu pour cet email.' } }];
}

const body = emailData.body.toLowerCase();
let blocked_topics = (user.blocked_topics || '').split(',').map(s => s.trim()).filter(Boolean);
let blocked_sources = (user.blocked_sources || '').split(',').map(s => s.trim()).filter(Boolean);
let preferences = user.preferences || '';
const changes = [];

const articleMatch = body.match(/article\s*(\d+)/i);
if (articleMatch && (body.includes('pas aime') || body.includes('n aime pas') || body.includes('inutile') || body.includes('enleve'))) {
  changes.push(`Article ${articleMatch[1]} signale comme non pertinent`);
}

const moinsMatch = body.match(/moins\s+(?:de\s+)?([a-zàâäéèêëïîôùûüç\s,]+)/i);
if (moinsMatch) {
  const topic = moinsMatch[1].split(/[,\.!\?]/)[0].trim();
  if (topic && !blocked_topics.map(t => t.toLowerCase()).includes(topic.toLowerCase())) {
    blocked_topics.push(topic);
    changes.push(`Topic bloque: ${topic}`);
  }
}

const plusMatch = body.match(/plus\s+(?:de\s+)?([a-zàâäéèêëïîôùûüç\s,]+)/i);
if (plusMatch) {
  const topic = plusMatch[1].split(/[,\.!\?]/)[0].trim();
  preferences = preferences ? `${preferences}; plus de ${topic}` : `plus de ${topic}`;
  changes.push(`Preference ajoutee: plus de ${topic}`);
}

const sourceMatch = body.match(/(?:evite|bloque|stop)\s+(?:la source\s+)?([a-z0-9\s]+)/i);
if (sourceMatch) {
  const src = sourceMatch[1].trim();
  if (src && !blocked_sources.map(s => s.toLowerCase()).includes(src.toLowerCase())) {
    blocked_sources.push(src);
    changes.push(`Source bloquee: ${src}`);
  }
}

if (changes.length === 0) {
  preferences = preferences ? `${preferences}; ${emailData.body.slice(0, 200)}` : emailData.body.slice(0, 200);
  changes.push('Feedback enregistre dans preferences');
}

return [{
  json: {
    success: true,
    rowId: user.username,
    username: user.username,
    email: user.email,
    blocked_topics: blocked_topics.join(','),
    blocked_sources: blocked_sources.join(','),
    preferences,
    changes,
    summary: changes.join('. ')
  }
}];

const fb = $('Process Feedback').first().json;
const items = fb.changes.map(c => `<li>${c}</li>`).join('');
const html = `<p>Bonjour ${fb.username},</p><p>Merci pour votre retour ! Persona a mis a jour vos preferences :</p><ul>${items}</ul><p>Votre prochaine newsletter en tiendra compte.</p><p style="color:#999;font-size:12px;">Persona - IA sans interface</p>`;
return { json: { html, email: fb.email } };
